import 'dart:async';

import 'package:dartssh2/dartssh2.dart';
import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart';

import '../constants.dart';

/// Per-install SSH credentials for the VM.
///
/// The root password is generated by the Android side on first use, kept
/// encrypted with an Android Keystore key and passed into the guest through
/// QEMU fw_cfg. When key-only login is on, the app authenticates with its
/// private key (also kept with the Keystore key).
class SshCredentials {
  const SshCredentials({
    required this.username,
    required this.password,
    this.privateKeyPem,
    this.keyOnly = false,
  });

  final String username;
  final String password;
  final String? privateKeyPem;
  final bool keyOnly;

  static const _channel = MethodChannel('com.ai2th.linxr/vm');
  static SshCredentials? _cached;

  bool get hasKey => privateKeyPem != null && privateKeyPem!.isNotEmpty;

  List<SSHKeyPair>? get identities {
    if (!hasKey) return null;
    try {
      return SSHKeyPair.fromPem(privateKeyPem!);
    } catch (e) {
      debugPrint('SSH private key could not be parsed: $e');
      return null;
    }
  }

  static Future<SshCredentials> load({bool refresh = false}) async {
    if (!refresh && _cached != null) return _cached!;
    try {
      final raw = await _channel.invokeMapMethod<String, dynamic>('getSshCredentials');
      final password = raw?['password'] as String?;
      if (password != null && password.isNotEmpty) {
        _cached = SshCredentials(
          username: (raw?['username'] as String?) ?? SshDefaults.username,
          password: password,
          privateKeyPem: raw?['privateKey'] as String?,
          keyOnly: (raw?['keyOnly'] as bool?) ?? false,
        );
        return _cached!;
      }
    } on PlatformException catch (e) {
      debugPrint('getSshCredentials failed: ${e.message}');
    } on MissingPluginException {
      // Widget tests and non-Android hosts.
    }
    return const SshCredentials(
      username: SshDefaults.username,
      password: SshDefaults.legacyPassword,
    );
  }

  /// Creates a new app key pair in the VM (the VM must be running) and
  /// stores the private key. Returns the refreshed credentials.
  static Future<SshCredentials> createKey() async {
    await _channel.invokeMethod<bool>('createSshKey');
    return load(refresh: true);
  }

  /// Opens an authenticated SSH connection to the VM.
  ///
  /// Tries the app key and the per-install password first. If the guest
  /// rejects them and still accepts the legacy password (a VM that has not
  /// applied the per-install password yet, e.g. its kernel cannot read
  /// fw_cfg), it logs in with that and sets the per-install password, so the
  /// shared default does not stay valid.
  static Future<SSHClient> connect({
    Duration connectTimeout = const Duration(seconds: 10),
    Duration authTimeout = const Duration(seconds: 25),
  }) async {
    final creds = await load();
    try {
      return await _open(creds.username, creds.password, creds.identities,
          connectTimeout, authTimeout);
    } on SSHAuthError {
      if (creds.keyOnly || creds.password == SshDefaults.legacyPassword) rethrow;
      final client = await _open(creds.username, SshDefaults.legacyPassword,
          null, connectTimeout, authTimeout);
      try {
        await client
            .run("printf 'root:%s\\n' '${creds.password}' | chpasswd")
            .timeout(authTimeout);
        debugPrint('Replaced the legacy VM root password with the per-install one');
      } catch (e) {
        debugPrint('Could not set the per-install root password: $e');
      }
      return client;
    }
  }

  static Future<SSHClient> _open(
    String username,
    String password,
    List<SSHKeyPair>? identities,
    Duration connectTimeout,
    Duration authTimeout,
  ) async {
    final socket = await SSHSocket.connect(
      SshDefaults.host,
      SshDefaults.port,
      timeout: connectTimeout,
    );
    final client = SSHClient(
      socket,
      username: username,
      identities: identities,
      onPasswordRequest: () => password,
    );
    try {
      await client.authenticated.timeout(authTimeout);
      return client;
    } catch (_) {
      client.close();
      rethrow;
    }
  }
}
